<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../../includes/staff/auth.php';require_once __DIR__.'/../../includes/staff/webauthn.php';
try{$p=json_decode(file_get_contents('php://input'),true);if(!is_array($p))throw new RuntimeException('Invalid request.');$c=$_SESSION['webauthn_auth_challenge']??'';$t=(int)($_SESSION['webauthn_auth_time']??0);unset($_SESSION['webauthn_auth_challenge'],$_SESSION['webauthn_auth_time']);if(!$c||!$t||time()-$t>120)throw new RuntimeException('Passkey request expired.');$id=$p['id']??'';$s=staff_db()->prepare("SELECT pk.*,s.id staff_id,s.email,s.first_name,s.last_name,s.is_active FROM staff_passkeys pk JOIN staff s ON s.id=pk.staff_id WHERE pk.credential_id=? LIMIT 1");$s->execute([$id]);$r=$s->fetch();if(!$r||!$r['is_active'])throw new RuntimeException('Passkey not linked to an active account.');$client=b64url_decode($p['response']['clientDataJSON']??'');$auth=b64url_decode($p['response']['authenticatorData']??'');$sig=b64url_decode($p['response']['signature']??'');verify_client_data($client,'webauthn.get',$c);$new=verify_authentication_signature($auth,$client,$sig,$r['public_key_pem']);$old=(int)$r['sign_count'];if($old>0&&$new>0&&$new<=$old)throw new RuntimeException('Passkey counter validation failed.');staff_db()->prepare("UPDATE staff_passkeys SET sign_count=?,last_used_at=NOW() WHERE id=?")->execute([$new,$r['id']]);session_regenerate_id(true);$_SESSION['staff_id']=$r['staff_id'];$_SESSION['csrf_token']=bin2hex(random_bytes(32));staff_db()->prepare("UPDATE staff SET failed_login_attempts=0,locked_until=NULL,last_login_at=NOW() WHERE id=?")->execute([$r['staff_id']]);remember_last_staff_account($r);log_activity('staff.login.passkey','staff',(string)$r['staff_id'],'Logged in with passkey.');echo json_encode(['ok'=>true,'redirect'=>ideare_root_url('staff/index.php')]);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()]);}
